433	func (cs *checkout) prepareOrderItemsAndShippingQuoteFromCart(ctx context.Context, userID, userCurrency string, address *pb.Address) (orderPrep, error) {
434		ctx, span := tracer.Start(ctx, "prepareOrderItemsAndShippingQuoteFromCart")
435		defer span.End()
436	
437		var out orderPrep
438		cartItems, err := cs.getUserCart(ctx, userID)
439		if err != nil {
440			return out, fmt.Errorf("cart failure: %+v", err)
441		}
442		orderItems, err := cs.prepOrderItems(ctx, cartItems, userCurrency)
443		if err != nil {
444			return out, fmt.Errorf("failed to prepare order: %+v", err)
445		}
446		shippingUSD, err := cs.quoteShipping(ctx, address, cartItems)
447		if err != nil {
448			return out, fmt.Errorf("shipping quote failure: %+v", err)
449		}
450		shippingPrice, err := cs.convertCurrency(ctx, shippingUSD, userCurrency)
451		if err != nil {
452			return out, fmt.Errorf("failed to convert shipping cost to currency: %+v", err)
453		}
454	
455		out.shippingCostLocalized = shippingPrice
456		out.cartItems = cartItems
457		out.orderItems = orderItems
458	
459		var totalCart int32
460		for _, ci := range cartItems {
461			totalCart += ci.Quantity
462		}
463		shippingCostFloat, _ := strconv.ParseFloat(fmt.Sprintf("%d.%02d", shippingPrice.GetUnits(), shippingPrice.GetNanos()/10000000), 64)
464	
465		span.SetAttributes(
466			attribute.Float64("demo.shipping.amount", shippingCostFloat),
467			attribute.Int("demo.cart.items.count", int(totalCart)),
468			attribute.Int("demo.order.items.count", len(orderItems)),
469		)
470		return out, nil
471	}
