485	func (cs *checkout) quoteShipping(ctx context.Context, address *pb.Address, items []*pb.CartItem) (*pb.Money, error) {
486		quotePayload, err := json.Marshal(map[string]interface{}{
487			"address": address,
488			"items":   items,
489		})
490		if err != nil {
491			return nil, fmt.Errorf("failed to marshal ship order request: %+v", err)
492		}
493	
494		req, err := http.NewRequestWithContext(ctx, "POST", cs.shippingSvcAddr+"/get-quote", bytes.NewBuffer(quotePayload))
495		if err != nil {
496			return nil, fmt.Errorf("failed to create request: %+v", err)
497		}
498		req.Header.Set("Content-Type", "application/json")
499		resp, err := cs.httpClient.Do(req)
500		if err != nil {
501			return nil, fmt.Errorf("failed POST to shipping service: %+v", err)
502		}
503		defer resp.Body.Close()
504	
505		if resp.StatusCode != http.StatusOK {
506			return nil, fmt.Errorf("failed POST to shipping service: expected 200, got %d", resp.StatusCode)
507		}
508	
509		shippingQuoteBytes, err := io.ReadAll(resp.Body)
510		if err != nil {
511			return nil, fmt.Errorf("failed to read shipping quote response: %+v", err)
512		}
513	
514		var quoteResp struct {
515			CostUsd *pb.Money `json:"cost_usd"`
516		}
517		if err := json.Unmarshal(shippingQuoteBytes, &quoteResp); err != nil {
518			return nil, fmt.Errorf("failed to unmarshal shipping quote: %+v", err)
519		}
520		if quoteResp.CostUsd == nil {
521			return nil, fmt.Errorf("shipping quote missing cost_usd field")
522		}
523	
524		return quoteResp.CostUsd, nil
525	}
