664	func (cs *checkout) sendToPostProcessor(ctx context.Context, result *pb.OrderResult) {
665		message, err := proto.Marshal(result)
666		if err != nil {
667			logger.Error(fmt.Sprintf("Failed to marshal message to protobuf: %+v", err))
668			return
669		}
670	
671		msg := sarama.ProducerMessage{
672			Topic: kafka.Topic,
673			Value: sarama.ByteEncoder(message),
674		}
675	
676		// Inject tracing info into message
677		span := createProducerSpan(ctx, &msg)
678		defer span.End()
679	
680		// Send message and handle response
681		startTime := time.Now()
682		select {
683		case cs.KafkaProducerClient.Input() <- &msg:
684			select {
685			case successMsg := <-cs.KafkaProducerClient.Successes():
686				span.SetAttributes(
687					attribute.Bool("messaging.kafka.producer.success", true),
688					attribute.Int("messaging.kafka.producer.duration_ms", int(time.Since(startTime).Milliseconds())),
689					attribute.KeyValue(semconv.MessagingKafkaMessageOffset(int(successMsg.Offset))),
690				)
691				logger.Info(fmt.Sprintf("Successful to write message. offset: %v, duration: %v", successMsg.Offset, time.Since(startTime)))
692			case errMsg := <-cs.KafkaProducerClient.Errors():
693				span.SetAttributes(
694					attribute.Bool("messaging.kafka.producer.success", false),
695					attribute.Int("messaging.kafka.producer.duration_ms", int(time.Since(startTime).Milliseconds())),
696				)
697				span.SetStatus(otelcodes.Error, errMsg.Err.Error())
698				logger.Error(fmt.Sprintf("Failed to write message: %v", errMsg.Err))
699			case <-ctx.Done():
700				span.SetAttributes(
701					attribute.Bool("messaging.kafka.producer.success", false),
702					attribute.Int("messaging.kafka.producer.duration_ms", int(time.Since(startTime).Milliseconds())),
703				)
704				span.SetStatus(otelcodes.Error, "Context cancelled: "+ctx.Err().Error())
705				logger.Warn(fmt.Sprintf("Context canceled before success message received: %v", ctx.Err()))
706			}
707		case <-ctx.Done():
708			span.SetAttributes(
709				attribute.Bool("messaging.kafka.producer.success", false),
710				attribute.Int("messaging.kafka.producer.duration_ms", int(time.Since(startTime).Milliseconds())),
711			)
712			span.SetStatus(otelcodes.Error, "Failed to send: "+ctx.Err().Error())
713			logger.Error(fmt.Sprintf("Failed to send message to Kafka within context deadline: %v", ctx.Err()))
714			return
715		}
716	
717		ffValue := flags.KafkaQueueProblems.Value(ctx, openfeature.EvaluationContext{})
718		if ffValue > 0 {
719			logger.Info("Warning: FeatureFlag 'kafkaQueueProblems' is activated, overloading queue now.")
720			for range ffValue {
721				go func(msg sarama.ProducerMessage) {
722					cs.KafkaProducerClient.Input() <- &msg
723					<-cs.KafkaProducerClient.Successes()
724				}(msg)
725			}
726			logger.Info(fmt.Sprintf("Done with #%d messages for overload simulation.", ffValue))
727		}
728	}
