730: func createProducerSpan(ctx context.Context, msg *sarama.ProducerMessage) trace.Span {
731: 	spanContext, span := tracer.Start(
732: 		ctx,
733: 		fmt.Sprintf("%s publish", msg.Topic),
734: 		trace.WithSpanKind(trace.SpanKindProducer),
735: 		trace.WithAttributes(
736: 			semconv.PeerService("kafka"),
737: 			semconv.NetworkTransportTCP,
738: 			semconv.MessagingSystemKafka,
739: 			semconv.MessagingDestinationName(msg.Topic),
740: 			semconv.MessagingOperationPublish,
741: 			semconv.MessagingKafkaDestinationPartition(int(msg.Partition)),
742: 		),
743: 	)
744: 
745: 	carrier := propagation.MapCarrier{}
746: 	propagator := otel.GetTextMapPropagator()
747: 	propagator.Inject(spanContext, carrier)
748: 
749: 	for key, value := range carrier {
750: 		msg.Headers = append(msg.Headers, sarama.RecordHeader{Key: []byte(key), Value: []byte(value)})
751: 	}
752: 
753: 	return span
