23: pub async fn create_quote_from_count(count: u32) -> Result<Quote, tonic::Status> {
24:     let f = match request_quote(count).await {
25:         Ok(float) => float,
26:         Err(err) => {
27:             let msg = format!("{}", err);
28:             return Err(tonic::Status::unknown(msg));
29:         }
30:     };
31: 
32:     ITEMS_SHIPPED_COUNTER.add(count as u64, &[]);
33: 
34:     Ok(get_active_span(|span| {
35:         let q = create_quote_from_float(f);
36:         if span.is_recording() {
37:             let cost = format!("{}", q);
38:             span.add_event(
39:                 "shipping.quote.received".to_string(),
40:                 vec![KeyValue::new("demo.shipping.cost.total", cost.clone())],
41:             );
42:             span.set_attribute(KeyValue::new("demo.shipping.cost.total", cost));
43:         }
44:         q
45:     }))
46: }
