48: async fn request_quote(count: u32) -> Result<f64, anyhow::Error> {
49:     let client = awc::Client::new();
50:     let quote_service_addr: String = format!(
51:         "{}{}",
52:         env::var("QUOTE_ADDR")
53:             .unwrap_or_else(|_| "http://quote:8090".to_string())
54:             .parse::<String>()
55:             .expect("Invalid quote service address"),
56:         "/getquote"
57:     );
58: 
59:     info!(
60:         name: "shipping.quote.requested",
61:         quote_service_addr = quote_service_addr.as_str(),
62:         "Requesting quote"
63:     );
64: 
65:     let mut reqbody = HashMap::new();
66:     reqbody.insert("numberOfItems", count);
67: 
68:     let mut response = client
69:         .post(quote_service_addr)
70:         .trace_request()
71:         .send_json(&reqbody)
72:         .await
73:         .map_err(|err| anyhow::anyhow!("Failed to call quote service: {err}"))?;
74: 
75:     let bytes = response
76:         .body()
77:         .await
78:         .context("Failed to read response body from quote service")?;
