1: #!/bin/sh
2: # Copyright The OpenTelemetry Authors
3: # SPDX-License-Identifier: Apache-2.0
4: 
5: 
6: # This script is used to generate protobuf files for all services.
7: # Useful to ensure code can compile without Docker, and provide hints for IDEs.
8: # Several dev tools including: cargo, protoc, python grpcio-tools, and rebar3 may be required to run this script.
9: 
10: base_dir=$(pwd)
11: 
12: gen_proto_dotnet() {
13:   echo "Generating .NET protobuf files for $1"
14:   cd "$base_dir"/src/"$1" || return
15:   mkdir -p ./src/protos/
16:   cp -r "$base_dir"/pb/ ./src/protos/
17:   cd "$base_dir" || return
18: }
19: 
20: gen_proto_elixir() {
21:   echo "Generating Elixir protobuf files for $1"
22:   cd "$base_dir"/src/"$1" || return
23:   mkdir -p proto
24:   cp "$base_dir"/pb/demo.proto ./proto/demo.proto
25:   rebar3 grpc_regen
26:   cd "$base_dir" || return
27: }
28: 
29: gen_proto_go() {
30:   echo "Generating Go protobuf files for $1"
31:   cd "$base_dir"/src/"$1" || return
32:   protoc -I ../../pb ./../../pb/demo.proto --go_out=./ --go-grpc_out=./
33:   cd "$base_dir" || return
34: }
